else:
	return self.custom.averages[0].oee_a


if value.mode == "Realtime":
	return value.tag["%sOee"%(value.interval)]["D"]
else:
	return 1-self.custom.averages[0].oee_a

if value.mode == "Realtime":
	return value.tag["%sOee"%(value.interval)]["O"]
